using System.Linq;
using UnityEngine;
public static class GridShiftTutorial {
 public static string Prefix="GS.Tutorial.";public static int Step=>PlayerPrefs.GetInt(Prefix+"Step",0);public static bool Completed=>PlayerPrefs.GetInt(Prefix+"Complete",0)==1;public static bool Skipped=>PlayerPrefs.GetInt(Prefix+"Skipped",0)==1;
 public static readonly string[] Titles={"Conheça a cidade","Ganhe velocidade","Sua central portátil","Conheça o Office","Acesse as operações","Seu primeiro pedido","Encontre sua frota","Mapa da operação","Cresça como empresa","Controles e conclusão"};
 public static string[] Instructions()=>new[]{"Use "+GridShiftControls.KeyName(GSAction.Forward)+" / "+GridShiftControls.KeyName(GSAction.Back)+" / "+GridShiftControls.KeyName(GSAction.Left)+" / "+GridShiftControls.KeyName(GSAction.Right)+" para caminhar. Observe a cidade antes de cruzar.","Segure "+GridShiftControls.KeyName(GSAction.Run)+" enquanto avança para correr.","Pressione "+GridShiftControls.KeyName(GSAction.Tablet)+" para abrir o tablet. Ele reúne os detalhes da empresa.","Aproxime-se da entrada da empresa e use "+GridShiftControls.KeyName(GSAction.Interact)+" para entrar no Office. As entregas continuam na cidade.","No Office, aproxime-se do PC e use "+GridShiftControls.KeyName(GSAction.Interact)+". Acesse a Central de Operações nativa e consulte as abas da empresa.","Em Disponíveis, aceite um contrato, ou crie um pedido na Operação. Peso, capacidade e locais válidos determinam a atribuição.","Selecione Acompanhar: o painel mostra o ID do veículo e o destino. No minimapa, carro amarelo = frota; losango ciano = destino.","Guarde o dispositivo e pressione "+GridShiftControls.KeyName(GSAction.Map)+" para ampliar/reduzir o mapa. Acompanhe os ícones discretos.","Conclua entregas para ganhar saldo. Abra Upgrades no painel ou "+GridShiftControls.KeyName(GSAction.Upgrades)+" para investir em capacidade, doca, frota e parceiros.","Abra "+GridShiftControls.KeyName(GSAction.Controls)+" para consultar ou remapear teclas. "+GridShiftControls.KeyName(GSAction.Tutorial)+" reabre este tutorial. ESC fecha a tela atual antes da pausa."};
 public static void Restore(TutorialSaveData data){PlayerPrefs.SetInt(Prefix+"Step",Mathf.Clamp(data?.step??0,0,9));PlayerPrefs.SetInt(Prefix+"Complete",data!=null&&data.complete?1:0);PlayerPrefs.SetInt(Prefix+"Skipped",data!=null&&data.skipped?1:0);PlayerPrefs.Save();}
 public static void Next(){int next=Step+1;if(next>=Titles.Length){PlayerPrefs.SetInt(Prefix+"Complete",1);PlayerPrefs.SetInt(Prefix+"Skipped",0);}else PlayerPrefs.SetInt(Prefix+"Step",next);PlayerPrefs.Save();}
 public static void Skip(){PlayerPrefs.SetInt(Prefix+"Skipped",1);PlayerPrefs.Save();}
 public static void Reopen(){PlayerPrefs.SetInt(Prefix+"Step",0);PlayerPrefs.SetInt(Prefix+"Complete",0);PlayerPrefs.SetInt(Prefix+"Skipped",0);PlayerPrefs.Save();}
 public static void Observe(PlayerMovement player,bool mapSeen,bool controlsSeen){if(Completed||Skipped||player==null)return;int step=Step;var manager=DeliveryManager.Instance;bool pass=step==0?player.MovementInput.sqrMagnitude>.1f:step==1?player.IsRunning:step==2?player.GetComponent<PortableTablet>()?.IsOpen==true:step==3?player.gameObject.scene.name=="Office":step==4?manager!=null&&manager.OperationsViewed:step==5?manager!=null&&manager.orders.Count>0:step==6?manager?.Selected?.vehicleId!=null:step==7?mapSeen:step==8?manager!=null&&manager.Progression.levels.Any(l=>l.level>0):step==9&&controlsSeen;if(pass)Next();}
}


